select abs(-3), coalesce(null, null, 'x'), ifnull(null, 2), iif(1 > 2, 'y', 'n'), nullif(3, 3), typeof(nullif(3, 4));
select instr('hello', 'll'), substr('hello', 2, 3), substr('hello', -3), replace('aaa', 'a', 'bb'), trim('  x  '), ltrim('xxy', 'x'), rtrim('yxx', 'x');
select lower('ÀB'), upper('straße'), length(x'0102'), octet_length('é'), quote('it''s'), quote(x'ab'), quote(1.5), char(72, 105);
select printf('%5.2f|%-5d|%x|%s|%q|%%', 3.14159, 42, 255, 'str', 'o''k'), format('%e', 12345.678);
select round(3.14159, 2), round(-2.5), round(1e20), ceil(1.2), floor(-1.2), trunc(-1.7), sign(-3), mod(7, 3);
select 9223372036854775807 + 1, -9223372036854775808 - 1, 2147483647 * 2147483647, 1e308 * 1e308, -1e308 * 1e308, 0.1 + 0.2;
select cast('12abc' as integer), cast('1e3' as real), cast(3.9 as int), cast(x'41' as text), cast(12 as blob), cast('  5 ' as numeric);
select '10' + 5, '3.0' * 2, 'a' + 1, 10 / 3, 10 % 0, 5 / 0.0, -0.0, 1 = 1.0, '1' = 1;
select 1 < 2 and null, 1 > 2 and null, null or 1, null or 0, not null, null between 1 and 2, 2 between 1 and 3;
select 'a' < 'b', 'B' < 'a', 'B' < 'a' collate nocase, 1 < 'a', x'00' > 'z', null < 1;
select 'abc' glob 'a*', 'ABC' like 'a_c', 'a%c' like 'a\%c' escape '\', 'x' regexp 'x';
select length(randomblob(0)), zeroblob(3), hex(zeroblob(2)), unhex('4142'), unicode('€'), likelihood(1, 0.5);
select min(3, 1, 2), max('a', 'b'), min(null, 1), sqlite_version(), typeof(sqlite_source_id());
select date('2024-02-29', '+1 year'), time('12:34:56', '+1 hour'), datetime('2000-01-01 00:00:00', '-1 second'), julianday('2000-01-01'), strftime('%Y-%m-%d %H:%M:%f %j %w %s', '2023-06-15 13:45:30.123'), unixepoch('1970-01-02'), date(0, 'unixepoch'), timediff('2024-01-01', '2023-01-01');
select log(100), log(2, 8), ln(1), exp(0), power(2, 10), sqrt(-1), atan2(1, 1), degrees(pi()), radians(180), cos(0), acos(2);
select json('{ "a" : [1, 2 ] }'), json_array_length('[1,2,3]'), json_type('{"a":1}', '$.a'), json_valid('{x}'), json_insert('{"a":1}', '$.b', 2), json_replace('[1,2]', '$[0]', 'x'), json_set('{}', '$.c', json('[3]')), json_remove('[1,2,3]', '$[1]'), json_patch('{"a":1,"b":2}', '{"b":null,"c":3}'), json_quote('x"y');
select key, value, type from json_each('{"a":1,"b":[2,3],"c":null}');
select fullkey, atom from json_tree('[1,{"x":2}]');
select json_group_array(v), json_group_object(k, v) from (select 'a' k, 1 v union all select 'b', 2);
select jsonb('[1]') = jsonb('[1]'), json(jsonb('{"a":2}')), '{"a":{"b":3}}' -> '$.a', '{"a":{"b":3}}' ->> '$.a.b';
select value from generate_series(1, 3);
select total(x), avg(x), count(x), group_concat(x, '-') from (select 1 x union all select null union all select 2.5);
select string_agg(n, ';' order by n desc), median(n) from (select 3 n union all select 1 union all select 2);
